INSERT INTO comment (heritage_id, user_id, username, avatar, content, likes, create_time) VALUES
(1, 1, 'admin', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face', '这个剪纸艺术真的太精美了！传统工艺的传承需要我们每个人的支持。', 12, '2024-01-15 10:30:00'),
(1, 2, 'testuser', 'https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face', '小时候奶奶也会剪纸，看到这些作品想起了童年时光。', 8, '2024-01-15 14:20:00'),
(1, 3, '文化爱好者', 'https://images.unsplash.com/photo-1507003211169-0177331693ae?w=150&h=150&fit=crop&crop=face', '传统文化是我们民族的根，一定要好好保护和传承下去。', 15, '2024-01-16 09:15:00'),
(2, 1, 'admin', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face', '皮影戏是我们的国粹，希望能有更多年轻人学习和传承。', 20, '2024-01-14 16:45:00'),
(2, 2, 'testuser', 'https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face', '上次去西安看了皮影戏表演，真的太震撼了！', 6, '2024-01-15 11:30:00'),
(3, 3, '文化爱好者', 'https://images.unsplash.com/photo-1507003211169-0177331693ae?w=150&h=150&fit=crop&crop=face', '苗绣的色彩搭配真是绝了，每一针一线都是艺术品。', 18, '2024-01-16 08:20:00'),
(3, 1, 'admin', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face', '传统手工艺需要与时俱进，在保留传统的同时创新发展。', 10, '2024-01-16 13:40:00'),
(4, 2, 'testuser', 'https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face', '昆曲的唱腔真是百听不厌，中华文化瑰宝！', 14, '2024-01-14 15:25:00'),
(5, 3, '文化爱好者', 'https://images.unsplash.com/photo-1507003211169-0177331693ae?w=150&h=150&fit=crop&crop=face', '景德镇的瓷器工艺举世闻名，为中国制造点赞！', 22, '2024-01-15 10:50:00'),
(5, 1, 'admin', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face', '希望更多年轻人了解和喜爱传统制瓷工艺。', 9, '2024-01-16 12:15:00');